from pathlib import Path
import hashlib,json
D=Path(__file__).resolve().parent;p=Path('rules/ark-nova.md');s=p.read_text()
assert hashlib.sha256(p.read_bytes()).hexdigest()==json.loads((D/'input-manifest.json').read_text())['hashes'][str(p.resolve())]
s=s.replace('source_pdf: "ark-nova-rules.pdf"','source_pdf: "ark-nova-rules.pdf"\nrulebook_version: "English base v1.2 + base glossary + official base errata/FAQ"')
s=s.replace('## Overview\n','## Overview\n\n**Scope:** original English base game, main rulebook **v1.2**, base glossary and official base FAQ. This explicitly upgrades the former v1.0 extraction. Marine Worlds and optional solo mode are excluded.\n')
s=s.replace('82 standard enclosures','90 standard enclosures').replace('24 kiosk / pavilion','34 kiosk / pavilion').replace('55 money tokens','70 money tokens').replace(', 1 tile for solo play, 25 player tokens',', 25 player tokens')
s=s.replace('place a 3-space enclosure on the indicated spaces with the side showing the number 3 (the empty side) up.','place an empty 3-space enclosure **and a kiosk** on the indicated spaces. The printed kiosk already counts as built; place a kiosk tile over it as a reminder. You may build adjacent to it.')
s=s.replace('its action is more powerful for the rest of the game.','its improved action is available **from your next action**, while it immediately counts as upgraded for conditions. The current action keeps the strength and kind set at its start; an upgrade gained during it does not add side-II capabilities to it.')
s=s.replace('- **Increase reputation:**','- **Increase reputation (strength 2):**').replace('- **Gain partner zoo:**','- **Gain partner zoo (strength 3):**').replace('- **Gain university:**','- **Gain university (strength 4):**').replace('- **Conservation project work:**','- **Conservation project work (strength 5):**')
s=s.replace('**End of the game.** If a player\'s Conservation counter and Appeal counter are ever','**End of the game.** Check **at the end of your own turn or during a break**. If your Conservation counter and Appeal counter are')
s=s.replace('The triggering player completes their turn','Appeal gained during another player\'s turn (for example from Polar Bear Exhibit) waits until the end of your own turn or a break to trigger the end, unless someone else triggers it first. The triggering player completes their turn')
s=s.replace('a player\'s Appeal and Conservation counters in the same scoring area (or crossed) → finish turn','at end of your own turn or during a break, your Appeal and Conservation counters in the same scoring area (or crossed) → finish turn')
s=s.replace('flip the smallest occupied standard enclosure that meets its requirements (including water/rock) back to empty','flip the smallest occupied standard enclosure that meets all its requirements (including water/rock) back to empty; if none does, use the smallest occupied enclosure meeting its size requirement; if none meets even the size, flip none')
s=s.replace('move your **Appeal counter back** as many steps as the animal\'s appeal value; flip the smallest occupied standard enclosure meeting the animal\'s requirements back to its empty side (or remove the appropriate player tokens from your special enclosure); place the Animal card on the discard pile.','first move your **Appeal counter back** by the animal\'s printed appeal, **before gaining conservation points**. Discard the Animal card and lose its icons; retain reputation, conservation points, appeal earned through its abilities and all earlier triggered benefits. For an animal eligible for a special enclosure, remove its indicated number of special-enclosure tokens if possible; only otherwise flip a standard enclosure. Flip the smallest occupied standard meeting all requirements, else the smallest meeting size alone, else none. This applies even to flock animals. Playing a new Release into the Wild project grants 1 reputation; supporting one already in play does not.')
s=s.replace('Some animals additionally require the enclosure to be next to one or two water and/or rock spaces.','Some animals additionally require the enclosure to be next to one or two water and/or rock spaces. Count distinct adjacent hexes: multiple edges touching the same water hex still count as only one, and a larger water area counts only the hexes actually adjacent.')
s=s.replace('When doing conservation project work you may also play','Tasks resolve in sequence: workers or other bonuses gained from an earlier task may be used on a later task in this same action. When doing conservation project work you may also play')
s=s.replace('plus your partner zoos and universities.','plus your partner zoos and universities. The card itself counts for its own effects; a double icon counts twice. Conservation-project icons do not count as icons in your zoo. Breeding Program projects (123–127) have the same requirement for all three reward spaces: choose any available one.')
s=s.replace('### Solo game\n'+s.split('### Solo game\n')[1].split('## Player Reference')[0],'')
p.write_text(s)
